<?php $url=static fn(string $parent):string=>'/catalog/batch?'.http_build_query(['space'=>$data['space']['id'],'parent'=>$parent]); ?>
<div class="page-heading"><div><p class="eyebrow">KATALOG</p><h1>Tags gemeinsam bearbeiten</h1><p class="lead"><?= $e($data['space']['name']) ?> · <?= $e($data['folder']['name']??'Bereichswurzel') ?></p></div><a href="<?= $e('/files?'.http_build_query(['space'=>$data['space']['id'],'parent'=>$data['parent']])) ?>">Zur Dateiliste</a></div>
<?php if($data['folder']!==null): ?><p><a href="<?= $e($url($data['folder']['parent_id'])) ?>">Übergeordneter Ordner</a> · <a href="<?= $e($url('')) ?>">Bereichswurzel</a></p><?php endif ?>
<section class="panel"><p>Bis zu 100 Dateien dieser Seite auswählen. Ein Tag wird hinzugefügt oder entfernt; Beschreibungen, andere Tags und Originale bleiben erhalten. Ordner werden nicht rekursiv übernommen. Jede Datei muss noch die angezeigte Datei- und Katalogrevision haben, sonst bleibt der gesamte Auftrag unverändert.</p>
<form method="post" action="/catalog/batch/change"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space']['id']) ?>"><input type="hidden" name="parent" value="<?= $e($data['parent']) ?>">
<label for="batch-tag">Tag</label><select id="batch-tag" name="tag" required><option value="">Tag auswählen</option><?php foreach($data['tags'] as$tag): ?><option value="<?= $e($tag['id']) ?>"><?= $e($tag['name']) ?></option><?php endforeach ?></select><label for="batch-tag-operation">Änderung</label><select id="batch-tag-operation" name="operation"><option value="add">Tag hinzufügen</option><option value="remove">Tag entfernen</option></select>
<div class="group-list"><?php foreach($data['rows'] as$row): ?><div class="group-row"><?php if($row['kind']==='file'): ?><label class="checkbox-label"><input type="checkbox" name="entries[]" value="<?= $e($row['id'].':'.$row['revision'].':'.$row['catalog_revision']) ?>"> <?= $e($row['name']) ?></label><?php else: ?><a href="<?= $e($url($row['id'])) ?>"><?= $e($row['name']) ?></a><?php endif ?></div><?php endforeach ?><?php if($data['rows']===[]): ?><p>Dieser Ordner ist leer.</p><?php endif ?></div>
<label><input type="checkbox" name="confirm" value="1" required> Diese Tagänderung für alle ausgewählten Dateien bestätigen.</label><button class="button" type="submit">Tagänderung gemeinsam speichern</button></form>
<?php if($data['next']!==null): ?><p><a href="<?= $e($url($data['parent']).'&after='.rawurlencode($data['next'])) ?>">Weitere Einträge</a></p><?php endif ?></section>
